<?php
declare(strict_types=1);
function openai_secret():string{$v=(string)setting('openai_api_key','');if(str_starts_with($v,'enc:'))$v=(string)(dec(substr($v,4))??'');return $v==='__EMPTY__'?'':trim($v);}
function openai_support_enabled():bool{return setting('openai_support_enabled','0')==='1'&&openai_secret()!=='';}
function openai_response_text(array $r):string{if(isset($r['output_text'])&&is_string($r['output_text']))return trim($r['output_text']);$text='';foreach((array)($r['output']??[]) as $item)foreach((array)($item['content']??[]) as $part)if(($part['type']??'')==='output_text')$text.=(string)($part['text']??'');return trim($text);}
function openai_ticket_suggestion(array $ticket,array $messages):string{if(!openai_support_enabled())throw new RuntimeException('AI support suggestions are not configured.');$lines=[];foreach(array_slice($messages,-12) as $m){if(!empty($m['is_internal']))continue;$lines[]=(!empty($m['is_staff'])?'Support':'Customer').': '.mb_substr(trim((string)($m['message']??'')),0,3000);}$input='Ticket subject: '.(string)($ticket['subject']??'')."\nCustomer: ".(string)($ticket['customer_name']??'Customer')."\nStatus: ".(string)($ticket['status']??'')."\n\nConversation:\n".implode("\n\n",$lines);$payload=['model'=>trim((string)setting('openai_support_model','gpt-5.6-luna'))?:'gpt-5.6-luna','instructions'=>'Draft a concise, friendly and professional customer-support reply for FoxNetwork. Reply in the same language as the customer. Use only facts present in the ticket. Never invent actions, refunds, completion times, technical results, or policies. If information is missing, ask a clear follow-up question. Return only the suggested reply text, without a subject line, analysis, markdown fences, or signature.','input'=>$input,'max_output_tokens'=>700,'store'=>false];$ch=curl_init('https://api.openai.com/v1/responses');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Authorization: Bearer '.openai_secret(),'Content-Type: application/json'],CURLOPT_TIMEOUT=>35]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);$json=json_decode((string)$raw,true)?:[];if($raw===false||$code<200||$code>=300)throw new RuntimeException((string)($json['error']['message']??$error?:('OpenAI HTTP '.$code)));$suggestion=openai_response_text($json);if($suggestion==='')throw new RuntimeException('OpenAI returned an empty suggestion.');return mb_substr($suggestion,0,20000);}
